А теперь посмотрим на вариант с атомиками,.
// Код офрмлен моделью Qwen 3.7
volatile char *VGA=(char *)0xA0000000L;

void plota(int x, int y, char color) {
 int byte_offset = (y << 6) + (y << 4) + (x >> 3);

 // 2. Получаем выровненный по 4 байтам адрес 32-битного слова
 // Операция & ~3 сбрасывает два младших бита адреса
 volatile unsigned int *word_ptr = (unsigned int *)((uintptr_t)VGA + (byte_offset & ~3));

 // 3. Вычисляем позицию бита в 32-битном слове (с учетом Little-Endian)
 // (byte_offset & 3) * 8 -> сдвиг байта внутри слова
 // 7 - (x & 7) -> позиция пикселя внутри байта (от старшего к младшему)
 int bit_shift = ((byte_offset & 3) << 3) + (7 - (x & 7));
 unsigned int bit_mask = 1U << bit_shift;

 // 4. Модификация памяти происходит без промежуточного чтения в регистры CPU
 if (color) {
 // OR: устанавливает нужный бит в 1
 __asm__ __volatile__ (
 "amoor.w zero, %1, (%0)"
 :
 : "r"(word_ptr), "r"(bit_mask)
 : "memory"
 );
 } else {
 // AND: сбрасывает нужный бит в 0 с помощью инвертированной маски
 unsigned int inv_mask = ~bit_mask;
 __asm__ __volatile__ (
 "amoand.w zero, %1, (%0)"
 :
 : "r"(word_ptr), "r"(inv_mask)
 : "memory"
 );
 }
}
Операция чтения из памяти видеоадаптера отсутствует. Упс, лучше так не использовать использовать адрес VGA так как он вызывает операцию чтения памяти [
lw a4,548(a4)
], это не та память которая нам нужна, задача кейса — использовать только команды записи.
