Лучше использовать константу:
#define VGA_BASE_ADDR ((volatile unsigned int *)0xA0000000L)

 volatile unsigned int *word_ptr = &VGA_BASE_ADDR[byte_offset >> 2];
И все это можно реализовать не вызывая жуткий ассемблерный макрос, через
встроенные функции GCC
(оказывается это стандарт С++11).
void plot(int x, int y, int color) {
 int byte_offset = (y * 80) + (x >> 3);
 int bit_pos = ((byte_offset & 3) << 3) | (~x & 7);

 // Получаем выровненный указатель, используя константный адрес
 volatile unsigned int *word_ptr = &VGA_BASE_ADDR[byte_offset >> 2];

 unsigned int bit_mask = 1U << bit_pos;

 // Используем встроенные атомики GCC, которые развернутся в AMO-инструкции
 if (color) {
 __atomic_fetch_or(word_ptr, bit_mask, __ATOMIC_RELAXED);
 } else {
 __atomic_fetch_and(word_ptr, ~bit_mask, __ATOMIC_RELAXED);
 }
}
А если еще добавить немного магии, то можно убрать ветвление. Это еще одна задача кейса, так как RISC‑V не любит ветвление, и при записи байта в память VGA в старом проекте никакого ветвления не было.
void plot(int x, int y, bool color) {
 int byte_offset = (y * 80) + (x >> 3);
 int bit_pos = ((byte_offset & 3) << 3) | (~x & 7);

 // Адрес вычисляется на базе константы (в ассемблере превратится в lui)
 volatile unsigned int *word_ptr = &VGA_BASE_ADDR[byte_offset >> 2];

 unsigned int bit_mask = 1U << bit_pos;

 // Branchless-магия для генерации масок без if-else:
 // Если color == 0, то c_mask = 0x00000000. Если color != 0, то c_mask = 0xFFFFFFFF
 unsigned int c_mask = -(unsigned int)(color != 0); 

 // Маска для ИЛИ: bit_mask если цвет 1, иначе 0
 unsigned int or_mask = bit_mask & c_mask;

 // Маска для И: инвертированная bit_mask если цвет 0, иначе 0xFFFFFFFF (не меняет биты)
 unsigned int and_mask = or_mask | ~bit_mask;

 // Вызов встроенных атомиков,
 __atomic_fetch_and(word_ptr, and_mask, __ATOMIC_RELAXED);
 __atomic_fetch_or(word_ptr, or_mask, __ATOMIC_RELAXED);
}
